key:
protocol Status { func text() -> String }
extension Status { func text() -> String { "Общее" } }
class BaseStatus: Status {
    func text() -> String { "База" }
}
class DeliveryStatus: BaseStatus {
    override func text() -> String { "Доставлено" }
}
let status: any Status = DeliveryStatus()
print(status.text())

Соответствие базы использует её метод; дальнейший class-override даёт Доставлено.

