import Foundation
class PlayerBadge: NSObject {
    func text() -> String { "Воспроизведение" }
}
print(PlayerBadge().text())

key:
import Foundation
class PlayerBadge: NSObject {
    @objc dynamic func text() -> String { "Воспроизведение" }
}
print(PlayerBadge().text())

Вывод «Воспроизведение». Вывод не меняется: разница в механизме вызова (Objective-C runtime), а не в результате и не в скорости.

