print(formatter.prefix(), formatter.body())

key:
class ReceiptFormatter {
    final func prefix() -> String { "Чек" }
    func body() -> String { "Обычный" }
}
class GiftFormatter: ReceiptFormatter {
    override func body() -> String { "Подарочный" }
}
let formatter: ReceiptFormatter = GiftFormatter()
print(formatter.prefix(), formatter.body())

Вывод «Чек Подарочный»; final-контракт не нарушен.
